BEGIN;
ALTER TABLE provider_connections ADD COLUMN capabilities text[] NOT NULL DEFAULT '{}',ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE plugin_entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),provider_connection_id uuid NOT NULL REFERENCES provider_connections(id),role text NOT NULL,capability text NOT NULL,allowed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_connection_id,role,capability));
CREATE TABLE meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),provider_connection_id uuid NOT NULL REFERENCES provider_connections(id),call_session_id uuid REFERENCES call_sessions(id),organizer_user_id uuid,external_event_id text,title text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,timezone text NOT NULL,attendee_name text NOT NULL,attendee_address text NOT NULL,attendee_consent_at timestamptz NOT NULL,join_url text,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed','rescheduled','cancelled','failed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_at>start_at));
CREATE TABLE integration_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),provider_connection_id uuid REFERENCES provider_connections(id),event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','processing','delivered','failed','cancelled')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE plugin_entitlements ENABLE ROW LEVEL SECURITY;ALTER TABLE plugin_entitlements FORCE ROW LEVEL SECURITY;ALTER TABLE meetings ENABLE ROW LEVEL SECURITY;ALTER TABLE meetings FORCE ROW LEVEL SECURITY;ALTER TABLE integration_events ENABLE ROW LEVEL SECURITY;ALTER TABLE integration_events FORCE ROW LEVEL SECURITY;
CREATE POLICY plugin_entitlements_isolation ON plugin_entitlements USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY meetings_isolation ON meetings USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY integration_events_isolation ON integration_events USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
